"""Extend only tablet/mobile filtering while retaining the selected desktop."""
import importlib.util
import sys
sys.dont_write_bytecode=True
from responsive_context import ROOT,ALIGNED,verify
spec=importlib.util.spec_from_file_location('responsive_aligned_source',ALIGNED/'tools/build.py')
source=importlib.util.module_from_spec(spec);spec.loader.exec_module(source)
PAGES=source.PAGES
LAUNCHER='''<button class="tide-button tide-button--secondary tide-responsive-filters__trigger" type="button" aria-haspopup="dialog" aria-controls="responsive-filters" aria-expanded="false" hidden><span>Filters</span><svg class="tide-icon" viewBox="0 0 15 15" fill="none" aria-hidden="true" focusable="false"><path d="M2 4h11M2 11h11M5 2v4M10 9v4" stroke="currentColor" stroke-linecap="round" stroke-width="1.25"/></svg></button>'''
DIALOG='''<dialog class="tide-responsive-filters__dialog" id="responsive-filters" aria-labelledby="responsive-filter-title"><header class="tide-responsive-filters__header"><h2 class="tide-responsive-filters__title" id="responsive-filter-title" tabindex="-1">Filters</h2><button class="tide-button tide-button--quiet tide-button--icon" type="button" aria-label="Cancel filter changes" data-filter-close><svg class="tide-icon" viewBox="0 0 15 15" fill="none" aria-hidden="true" focusable="false"><path d="m4 4 7 7M11 4l-7 7" stroke="currentColor" stroke-linecap="round" stroke-width="1.25"/></svg></button><p class="tide-responsive-filters__description">Choose dates and categories. Changes apply together.</p></header><div class="tide-responsive-filters__body"></div><footer class="tide-responsive-filters__footer"><div class="tide-responsive-filters__footer-row"><button class="tide-button tide-button--quiet" type="button" data-filter-reset>Reset filters</button><p class="tide-responsive-filters__count" role="status" aria-live="polite" aria-atomic="true"></p></div></footer></dialog>'''

def page(filename):
    html=source.page(filename)
    html=html.replace('href="../sidebar-alignment.css"','href="../../margin-reveal-aligned/sidebar-alignment.css"',1)
    # The responsive listener must register before the preserved desktop adapter.
    html=html.replace('<script src="../../contained-margin-filters/slide-adapter.js"','<script src="../responsive-filters.js" defer></script>\n<script src="../../contained-margin-filters/slide-adapter.js"',1)
    html=html.replace('</head>','<link rel="stylesheet" href="../responsive-filters.css">\n</head>',1)
    if 'id="event-search-form"' in html:
        html=html.replace('<details class="tide-expandable tide-app__filters">',LAUNCHER+'<details class="tide-expandable tide-app__filters">',1)
        html=html.replace('</body>',DIALOG+'\n</body>',1)
    return html

def overview():
    return '''<!doctype html><html lang="en" data-theme="bumble" data-mode="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Margin Reveal · Tablet and mobile filters · Burque</title><link rel="stylesheet" href="../base/kit/css/tide.css"><link rel="stylesheet" href="../css/review.css"><link rel="stylesheet" href="review.css"><script src="review.js" defer></script></head><body class="tide tide-study-review"><a class="tide-skip-link" href="#study">Skip to the study</a><header class="tide-study-review__header"><div><p class="tide-eyebrow">Margin Reveal / Responsive filters</p><h1>Room to choose.</h1><p>The approved desktop stays exactly as selected. On smaller screens, the same filters get their own space, with the action always in reach.</p><div class="tide-row tide-study-review__badges"><span class="tide-badge">Desktop preserved</span><span class="tide-badge">Existing kit controls</span><span class="tide-badge">48 working events</span></div></div><a class="tide-button tide-button--secondary" href="../margin-reveal-aligned/demo/index.html" target="_blank" rel="noopener">Approved desktop<span class="tide-sr-only"> in a new tab</span></a></header><main id="study"><section class="tide-study-review__section" aria-labelledby="phone-title"><header class="tide-study-review__section-header"><div><p class="tide-eyebrow">01 / Mobile</p><h2 id="phone-title">A dedicated filter screen.</h2><p>Tap Filters. Dates and categories open full screen. Change your choices, reset them, or cancel; Show events applies them together and returns to the lineup.</p></div><a class="tide-button tide-button--secondary" href="demo/index.html" target="_blank" rel="noopener">Open live prototype<span class="tide-sr-only"> in a new tab</span></a></header><figure class="tide-study-review__figure"><figcaption><span>Search stays in the list · Filters get the screen · Apply stays visible</span><span>390 × 844 · live HTML</span></figcaption><div class="tide-responsive-filters-review__viewport" data-width="390" data-height="844"><iframe src="demo/index.html" title="Mobile: working filter screen" loading="eager"></iframe></div></figure></section><section class="tide-study-review__section" aria-labelledby="tablet-title"><header class="tide-study-review__section-header"><div><p class="tide-eyebrow">02 / Tablet</p><h2 id="tablet-title">A drawer, without a tighter list.</h2><p>The filters open over the right edge. The underlying list and selected event keep their space. The controls and draft/apply behavior match the phone.</p></div></header><figure class="tide-study-review__figure"><figcaption><span>Tap Filters in the list to open the drawer</span><span>1024 × 768 · live HTML</span></figcaption><div class="tide-responsive-filters-review__viewport" data-width="1024" data-height="768"><iframe src="demo/index.html" title="Tablet: working filter drawer" loading="lazy"></iframe></div></figure></section></main><footer class="tide-study-review__footer"><nav aria-label="Study documentation"><a class="tide-link" href="../margin-reveal-aligned/index.html">Preserved desktop review</a><a class="tide-link" href="README.md">Behavior and component ownership</a></nav><p>This is an isolated responsive proposal. The maintained kit and approved desktop release remain unchanged.</p></footer></body></html>'''

def outputs():return {'index.html':overview(),**{'demo/'+name:page(name) for name in PAGES}}
if __name__=='__main__':
    verify();generated=outputs()
    for name,content in generated.items():
        target=ROOT/name;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(content,encoding='utf-8',newline='\n')
    verify();print(f'{len(generated)} HTML documents built; original desktop markup preserved.')
